@tool
extends Node

func run() -> Dictionary:
	var rep := {"quarantined": [], "moved": [], "deleted": [], "errors": []}
	var f := FileAccess.open("res://tools/gc_cleanup_ops.json", FileAccess.READ)
	if f == null:
		rep["errors"].append({"op": "startup", "src": "ops", "error": "ops file missing"})
		return rep
	var txt := f.get_as_text()
	f.close()
	var ops = JSON.parse_string(txt)
	if ops == null:
		rep["errors"].append({"op": "startup", "src": "ops", "error": "ops JSON parse failed"})
		return rep
	var d := DirAccess.open("E:/")
	if d == null:
		rep["errors"].append({"op": "startup", "src": "da", "error": "DirAccess.open E:/ failed"})
		return rep
	var PROJ := "ghost-company-main/"
	var QUAR := "ghost-company-quarantine/"
	for src in ops.get("quarantine", []):
		var s := String(src)
		var from_rel := PROJ + s.substr(6)
		var to_rel := QUAR + s.substr(6)
		if not (d.dir_exists(from_rel) or FileAccess.file_exists(s)):
			rep["errors"].append({"op": "quarantine", "src": s, "error": "missing"})
			continue
		var to_parent := to_rel.get_base_dir()
		if not d.dir_exists(to_parent):
			d.make_dir_recursive(to_parent)
		var err := d.rename(from_rel, to_rel)
		if err == OK:
			rep["quarantined"].append(s)
			if FileAccess.file_exists(s + ".import"):
				d.remove(from_rel + ".import")
		else:
			rep["errors"].append({"op": "quarantine", "src": s, "error": str(err)})
	for m in ops.get("move", []):
		var sf := String(m["from"])
		var st := String(m["to"])
		var from_rel := PROJ + sf.substr(6)
		var to_rel := PROJ + st.substr(6)
		if not (d.dir_exists(from_rel) or FileAccess.file_exists(sf)):
			rep["errors"].append({"op": "move", "src": sf, "error": "missing"})
			continue
		var to_parent := to_rel.get_base_dir()
		if not d.dir_exists(to_parent):
			d.make_dir_recursive(to_parent)
		var err2 := d.rename(from_rel, to_rel)
		if err2 == OK:
			rep["moved"].append(sf + " -> " + st)
			if FileAccess.file_exists(sf + ".import"):
				d.rename(from_rel + ".import", to_rel + ".import")
		else:
			rep["errors"].append({"op": "move", "src": sf, "error": str(err2)})
	for src in ops.get("delete", []):
		var s := String(src)
		var from_rel := PROJ + s.substr(6)
		if d.dir_exists(from_rel):
			var okdel := d.remove_recursive(from_rel)
			if okdel == OK:
				rep["deleted"].append(s)
			else:
				rep["errors"].append({"op": "delete", "src": s, "error": str(okdel)})
		elif FileAccess.file_exists(s):
			d.remove(from_rel)
			if FileAccess.file_exists(s + ".import"):
				d.remove(from_rel + ".import")
			rep["deleted"].append(s)
		else:
			rep["errors"].append({"op": "delete", "src": s, "error": "missing"})
	var rf := FileAccess.open("res://tools/gc_cleanup_report.gd", FileAccess.WRITE)
	if rf:
		rf.store_string("# GC_CLEANUP_REPORT " + JSON.stringify(rep))
		rf.close()
	if FileAccess.file_exists("res://tools/gc_cleanup_ops.json"):
		d.rename(PROJ + "tools/gc_cleanup_ops.json", PROJ + "tools/gc_cleanup_ops.done.json")
	return rep
